import{lt as e,q as t,ut as n,wt as r}from"./chunks/framework.DadrUYml.js";var i=JSON.parse(`{"title":"考试","description":"华南理工大学本科考试、缓考办理与期末复习指南","frontmatter":{"lang":"zh-CN","title":"考试","description":"华南理工大学本科考试、缓考办理与期末复习指南"},"headers":[],"relativePath":"learn/curricular/exam.md","filePath":"learn/curricular/exam.md","lastUpdated":1793435255000}`),a={name:`learn/curricular/exam.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /learn/curricular/exam.md for this page in Markdown format</div><h1 id="考试" tabindex="-1">考试 <a class="header-anchor" href="#考试" aria-label="Permalink to “考试”">​</a></h1><p>TODO: 补充考核规章与应考细则：</p><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 考场纪律与违纪处理：带手机/作弊的严肃后果与学籍处分规定</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 查分与复核：期末成绩异议的申请复核流程与时间窗口</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 课程考核方式说明：各类型课程（必修/选修/通识）的考核形式与成绩构成</li></ul><h2 id="缓考" tabindex="-1">缓考 <a class="header-anchor" href="#缓考" aria-label="Permalink to “缓考”">​</a></h2><p><a href="./deferred_exam">《缓考申请攻略：别把缺考赌成缓考》</a>是一份经过两次实际办理验证的缓考 SOP，覆盖因病或课程冲突的证明材料、申请单填写、两栏审批与三处盖章、回执交付，以及下一学期的“重考报名确认”。</p><h2 id="自学科学与技术" tabindex="-1">自学科学与技术 <a class="header-anchor" href="#自学科学与技术" aria-label="Permalink to “自学科学与技术”">​</a></h2><p><a href="./self_study_science_technology">《自学科学与技术：反内卷的大学生存工程学》</a>是一份完整的大学期末考试方法论，讨论目标分数管理、科目分诊、真题逆向、考场控制，以及如何用 Agent 把零散资料转化为可执行的复习系统。</p><h2 id="期末复习工具" tabindex="-1">期末复习工具 <a class="header-anchor" href="#期末复习工具" aria-label="Permalink to “期末复习工具”">​</a></h2><p>如果复习时间有限、资料零散，可以使用 <a href="https://github.com/Wh1te358/exam-hacker" target="_blank" rel="noreferrer">Exam Hacker</a> 将教材、课件、真题和笔记整理成目标分数导向的复习方案。</p><p>它由一个入口 Skill 和五个专用 Skill 组成：先分诊资料、目标和时间，再按需要压缩知识链、完整解题、主动练习，并根据掌握证据重排计划。对于扫描版 PDF，它会先检测可读性；只有实际检查过的页面才会被当作视觉证据。</p><h2 id="课程-pdf-下载工具" tabindex="-1">课程 PDF 下载工具 <a class="header-anchor" href="#课程-pdf-下载工具" aria-label="Permalink to “课程 PDF 下载工具”">​</a></h2><p>课程中心里的 PDF 课件只有预览入口、没有下载按钮时，可以使用 Chrome 扩展 <a href="https://github.com/Wh1te358/scut-course-pdf-downloader" target="_blank" rel="noreferrer">SCUT Course PDF Downloader</a>。它支持 PDF 直链，以及地址中包含原始 PDF 的 PDF.js 预览页。</p><p>当前版本只处理 PDF，不识别 PPT、PPTX、视频或课程主页。仓库 README 提供了安装、测试和使用步骤。</p><h2 id="大学物理" tabindex="-1">大学物理 <a class="header-anchor" href="#大学物理" aria-label="Permalink to “大学物理”">​</a></h2><p>这里是 <em>Oplisty</em> 整理的 <strong>华南理工大学 大学物理 复习笔记</strong>： <a href="https://www.zhihu.com/column/c_1888956732467823738" target="_blank" rel="noreferrer">大物定理汇总期末速成版</a></p><p>可供大学物理上学习、复习参考。</p>`,17)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};